import React, { useEffect } from 'react';
import AnimatedBackground from '../components/AnimatedBackground.jsx';
import HexagonPulseBackground from '../components/HexagonPulseBackground';
import { Link } from 'react-router-dom';
import img1 from '../assets/highlight1.png';
import img2 from '../assets/highlight2.png';
import img3 from '../assets/highlight3.png';
import img4 from '../assets/highlight4.png';

export default function PainlessCanalTreatment() {
  useEffect(() => {
    const io = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) entry.target.classList.add('is-visible');
      });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, []);

  const canalImages = [img1, img2, img3, img4];

  function CanalImageSlider() {
    const imagesPerSlide = 3;
    const totalSlides = Math.ceil(canalImages.length / imagesPerSlide);
    const [current, setCurrent] = React.useState(0);
    const next = () => setCurrent(c => (c + 1 < totalSlides ? c + 1 : c));
    const prev = () => setCurrent(c => (c - 1 >= 0 ? c - 1 : 0));
    const goTo = idx => setCurrent(idx);
    const slideImages = canalImages.slice(current * imagesPerSlide, current * imagesPerSlide + imagesPerSlide);
    return (
      <div className="w-full flex flex-col items-center">
        <div className="flex items-center justify-center gap-4 w-full">
          <button onClick={prev} className="bg-white border border-gray-300 text-sky-700 rounded-full p-3 shadow-lg hover:bg-sky-100 transition">&#8592;</button>
          <div className="flex gap-8">
            {slideImages.map((src, idx) => (
              <figure key={current * imagesPerSlide + idx} className={`reveal shadow-xl transform transition hover:scale-105 rounded-2xl overflow-hidden bg-gradient-to-tr from-white via-sky-100 to-pink-100 flex flex-col`}>
                <div className="relative w-full h-56 flex items-center justify-center">
                  <img src={src} alt={`rootcase-${current * imagesPerSlide + idx + 1}`} className="w-full h-full object-cover rounded-2xl scale-105" />
                  <div className="absolute top-2 left-2 bg-white/80 rounded-full px-3 py-1 text-xs font-bold text-sky-700 shadow">Case {current * imagesPerSlide + idx + 1}</div>
                </div>
                <figcaption className="p-4 bg-white/80 backdrop-blur-md flex-1 flex items-center justify-center">
                  <p className="text-sm text-gray-700 font-semibold text-center">Successful canal therapy restoring function and comfort.</p>
                </figcaption>
              </figure>
            ))}
          </div>
          <button onClick={next} className="bg-white border border-gray-300 text-sky-700 rounded-full p-3 shadow-lg hover:bg-sky-100 transition">&#8594;</button>
        </div>
        <div className="flex justify-center mt-6 gap-2">
          {Array.from({ length: totalSlides }).map((_, idx) => (
            <button
              key={idx}
              onClick={() => goTo(idx)}
              className={`w-3 h-3 rounded-full ${current === idx ? 'bg-sky-500' : 'bg-gray-300'} transition`}
              aria-label={`Go to slide ${idx + 1}`}
            />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="relative min-h-screen bg-white overflow-x-hidden">
      <div className="absolute inset-0 -z-30 opacity-95 pointer-events-none" aria-hidden>
        <AnimatedBackground />
      </div>
      <div className="absolute inset-0 -z-20 pointer-events-none" aria-hidden>
        <HexagonPulseBackground />
      </div>

      <header className="relative max-w-6xl mx-auto px-6 py-24 text-center">
        <div className="inline-block bg-gradient-to-r from-white/80 to-white/60 backdrop-blur-md rounded-3xl px-8 py-10 shadow-2xl">
          <h1 className="text-3xl md:text-4xl font-extrabold text-sky-800 mb-3">Painless Canal Treatment — Gentle Endodontics</h1>
          <p className="text-gray-700 max-w-3xl mx-auto mb-6">Modern root canal treatment relieves pain, removes infection, and saves teeth using precise, minimally invasive techniques and effective anaesthesia for comfortable care.</p>
          <div className="flex justify-center gap-4">
                        <a href="#gallery" className="px-6 py-2 rounded-full border border-sky-600 text-sky-600 font-semibold hover:bg-sky-50 transition">View Cases</a>
          </div>
        </div>
      </header>

      <section id="gallery" className="max-w-6xl mx-auto px-6 py-12">
        <h2 className="text-2xl md:text-3xl font-bold text-sky-800 mb-6 text-center reveal">Case Highlights</h2>
        <CanalImageSlider />
      </section>

      <section className="w-full px-6 md:px-12 py-12 bg-white">
        <div className="max-w-screen-xl mx-auto">
          <h3 className="text-2xl md:text-3xl font-bold text-sky-800 mb-4 text-center reveal">What makes treatment painless?</h3>
          <article className="text-gray-700 leading-relaxed text-lg reveal" style={{ textAlign: 'justify' }}>
            Advances in local anaesthesia, instrumentation, and magnification have transformed root canal therapy. Effective local anaesthesia isolates the tooth so patients experience minimal discomfort during treatment. We use gentle infiltration and nerve-block techniques as indicated and confirm anaesthesia before proceeding. Modern instruments are designed to shape the root canal precisely while reducing stress on the tooth and surrounding tissues.

            Endodontic microscopes and digital radiography improve visualization, allowing clinicians to locate all canals, remove infected tissue efficiently, and avoid unnecessary tooth removal. Sterile technique and modern irrigation solutions disinfect canals effectively, and bioactive sealers improve long-term outcomes. These technologies together reduce treatment time and postoperative discomfort compared with older methods.

            Our approach includes careful patient communication, short appointments when needed, and prescription of appropriate analgesics post-operatively if required. Patients with dental anxiety benefit from pre-treatment counselling, nitrous oxide sedation, or oral medication. We individualize care for patients with complex anatomy or medical considerations and refer for specialist endodontic care when a case requires advanced surgical or retreatment options.

            Saving a tooth with root canal treatment preserves natural function and prevents the need for extraction and replacement, which often involves more extensive restorative work. Early diagnosis and treatment of infected or symptomatic teeth improves success rates and reduces complications. Follow-up visits ensure healing and the final restoration — often a crown — protects the treated tooth for years of predictable function.

            If you are experiencing persistent tooth pain or sensitivity, book a consultation. We’ll assess the tooth, discuss diagnostic options, and outline a comfortable, evidence-based treatment plan tailored to your needs.
          </article>
        </div>
      </section>

      <style>{`
  .reveal { opacity: 0; transform: translateY(28px) scale(0.995); will-change: transform, opacity; }
  .reveal.is-visible { animation: revealIn 700ms cubic-bezier(.22,.9,.36,1) both; }
  @keyframes revealIn { from { opacity: 0; transform: translateY(28px) scale(0.995); } to { opacity: 1; transform: translateY(0) scale(1); } }
  .reveal { animation-delay: var(--delay, 0ms); }

  /* calming ribbon/wave accent in header */
  header::before { content: ''; position: absolute; left: -4%; top: 16%; width: 108%; height: 220px; background: radial-gradient(ellipse at center, rgba(99,102,241,0.05), rgba(6,182,212,0.04)); transform: rotate(-3deg); z-index: -1; border-radius: 24px; }
  header .backdrop-blur-md { backdrop-filter: blur(6px); }
      `}</style>
    </div>
  );
}
